export function FinancialReportsScreen(){const [tab,setTab]=useState(reportTabs[0] ?? "Profit & Loss");const rows=tab==="Aging Report"?[{account:"Aurora Apparels",debit:money(482000),credit:"—",balance:money(482000),period:"0–30 days"},{account:"Northern Knitwear",debit:money(630000),credit:"—",balance:money(630000),period:"31–60 days"}]:[{account:"Sales revenue",debit:"—",credit:money(6248000),balance:money(6248000),period:"Sep 2026"},{account:"Cost of goods sold",debit:money(4126000),credit:"—",balance:money(4126000),period:"Sep 2026"},{account:"Operating expense",debit:money(588000),credit:"—",balance:money(588000),period:"Sep 2026"},{account:"Gross profit",debit:"—",credit:money(1534000),balance:money(1534000),period:"Sep 2026"}];return <><PageHeader eyebrow="Accounting" title="Financial reports" description="Standard financial statements and account-level analysis." action="Export report" onAction={()=>submitWithToast(`${tab} export prepared`)}/><div className="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{reportTabs.map((report)=><button key={report} onClick={()=>setTab(report)} className={`rounded-lg border p-4 text-left shadow-card transition-colors ${tab===report?"border-primary bg-primary text-primary-foreground":"bg-card hover:border-primary/30 hover:bg-accent"}`}><FileText className="mb-4 size-4"/><div className="text-xs font-semibold">{report}</div><div className={`mt-1 text-[10px] ${tab===report?"text-primary-foreground/70":"text-muted-foreground"}`}>September 2026</div></button>)}</div><Panel title={tab} subtitle="Financial year 2026 · amounts in BDT"><div className="flex flex-wrap items-end gap-3 border-b bg-surface-subtle p-3"><Field label="From" type="date" defaultValue="2026-09-01"/><Field label="To" type="date" defaultValue="2026-09-30"/><Button size="sm" className="h-9" onClick={()=>toast.success("Report refreshed")}>Run report</Button></div><div className="p-4"><MiniStats items={[{label:"Revenue",value:money(6248000),tone:"up"},{label:"Expenses",value:money(4714000)},{label:"Net position",value:money(1534000),tone:"up"}]}/></div><DataTable searchable={false} columns={[{key:"account",label:"Account / Party"},{key:"period",label:"Period"},{key:"debit",label:"Debit",align:"right"},{key:"credit",label:"Credit",align:"right"},{key:"balance",label:"Balance",align:"right"}]} rows={rows}/></Panel></>}

export function WarehousesScreen(){const [tab,setTab]=useState("Warehouse stock");return <><PageHeader eyebrow="Locations" title="Multi-warehouse" description="Track storage locations, warehouse-level stock and internal transfers." action="Add warehouse"/><MetricStrip items={[{label:"Warehouses",value:"3",detail:"All locations active"},{label:"Tejgaon stock",value:money(3920000),detail:"624 SKUs"},{label:"Gazipur stock",value:money(2850000),detail:"418 SKUs"},{label:"In transfer",value:money(168000),detail:"4 open transfers"}]}/><Panel title="Warehouse operations"><TabsBar tabs={["Warehouse stock","Warehouse list","Stock transfer"]} active={tab} onChange={setTab}/>{tab==="Stock transfer"?<FormGrid title="Create stock transfer" fields={["Transfer number","From warehouse","To warehouse","Product / SKU","Quantity","Transfer date","Notes"]}/>:<DataTable columns={[{key:"sku",label:"SKU"},{key:"product",label:"Product"},{key:"warehouse",label:"Warehouse"},{key:"available",label:"Available",align:"right"},{key:"reserved",label:"Reserved",align:"right"},{key:"status",label:"Status",status:true}]} rows={inventoryRows}/>}</Panel></>}

export function AnalyticsScreen(){const reports=["Sales by buyer","Product profitability","Purchase by supplier","Inventory valuation","Receivable aging","Payable aging","VAT summary","Warehouse movement"];return <><PageHeader eyebrow="Reports" title="Reports & analytics center" description="Run operational and financial reports with consistent filters and exports." action="Saved reports"/><div className="mb-4 grid border-l border-t bg-card sm:grid-cols-2 lg:grid-cols-4">{reports.map((r,i)=><button type="button" key={r} className="group border-b border-r p-4 text-left hover:bg-muted"><FileText className="mb-5 size-5 text-primary"/><div className="text-xs font-semibold">{r}</div><div className="mt-1 text-[10px] text-muted-foreground">Updated {i<3?"today":"yesterday"}</div><ArrowRight className="ml-auto mt-3 size-3.5 text-muted-foreground group-hover:text-primary"/></button>)}</div><div className="grid gap-4 xl:grid-cols-[1fr_2fr]"><Panel title="Report filters"><div className="grid gap-3 p-4"><SelectField label="Report" options={reports}/><Field label="From date" type="date" defaultValue="2026-09-01"/><Field label="To date" type="date" defaultValue="2026-09-30"/><SelectField label="Warehouse" options={["All warehouses","Tejgaon","Gazipur","Narayanganj"]}/><Button size="sm" className="rounded-sm">Generate report</Button></div></Panel><Panel title="Sales by buyer" action={<Button variant="outline" size="sm" className="rounded-sm shadow-none"><Download/>Excel / PDF</Button>}><div className="h-72 p-4"><ResponsiveContainer width="100%" height="100%"><BarChart data={chartData}><CartesianGrid stroke="var(--border)" vertical={false}/><XAxis dataKey="month" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><Tooltip/><Bar dataKey="sales" fill="var(--primary)" radius={0}/></BarChart></ResponsiveContainer></div></Panel></div></>}

export function SettingsScreen(){const [tab,setTab]=useState("Company profile");const tabs=["Company profile","Users & roles","Numbering","Tax & currency","Backup & export","Notifications"];return <><PageHeader eyebrow="Administration" title="Settings" description="Company identity, access control and system-wide defaults." action="Save changes"/><Panel title="System configuration"><TabsBar tabs={tabs} active={tab} onChange={setTab}/>{tab==="Users & roles"?<DataTable columns={[{key:"name",label:"User"},{key:"email",label:"Email"},{key:"role",label:"Role"},{key:"location",label:"Location"},{key:"status",label:"Status",status:true}]} rows={[{name:"Nadia Rahman",email:"nadia@garmenttrade.com",role:"Admin",location:"Dhaka",status:"Active"},{name:"Arif Hasan",email:"arif@garmenttrade.com",role:"Manager",location:"Gazipur",status:"Active"},{name:"Maliha Islam",email:"maliha@garmenttrade.com",role:"Staff",location:"Dhaka",status:"Active"}]}/>:tab==="Notifications"?<div className="divide-y">{[["Low stock alerts","Notify when stock falls below the product minimum"],["Approval reminders","Daily reminder for requests awaiting action"],["Payment due alerts","Notify seven days before buyer or supplier due date"],["Daily summary","Receive a closing summary of sales, purchase and cash"]].map((n,i)=><div key={n[0]} className="flex items-center justify-between p-4"><div><div className="text-xs font-semibold">{n[0]}</div><div className="text-[10px] text-muted-foreground">{n[1]}</div></div><Switch defaultChecked={i<3}/></div>)}</div>:<div className="p-4"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><Field label={tab==="Company profile"?"Company name":"Configuration name"} defaultValue={tab==="Company profile"?"GarmentTrade Accessories":"GT-Default"}/><Field label={tab==="Company profile"?"Phone":"Prefix"} defaultValue={tab==="Company profile"?"+880 2 5512 4400":"INV-{YYYY}-{####}"}/><Field label={tab==="Company profile"?"Email":"Default currency"} defaultValue={tab==="Company profile"?"accounts@garmenttrade.com":"BDT (৳)"}/><Field label="Address / Notes" defaultValue="Tejgaon Industrial Area, Dhaka 1208"/></div><div className="mt-4 border border-dashed p-5 text-center text-xs text-muted-foreground"><Building2 className="mx-auto mb-2 size-5"/>Company logo and invoice letterhead assets</div></div>}</Panel></>}
